import pathlib,tempfile,subprocess,json,hashlib,re,struct,time
R=pathlib.Path('/home/mii/code/konOSuba/biomiya');C=R/'core-s';D=R/'docs/workflows/bootstrap-b3';q='/usr/bin/qemu-riscv64';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();result={'hashes':{},'checks':[]}
for rev in ['H-r3','L-r2','F-r3','M-r3','I-r2']:
 c=json.loads((D/f'{rev}-candidate.json').read_text())
 for p,h in c['files'].items():assert sha(R/p)==h,(rev,p)
 if isinstance(c.get('evidence'),dict):
  for p,h in c['evidence'].items():assert sha(D/p)==h,(rev,p)
 result['hashes'][rev]='matched'
author=json.loads((D/'I-r2-clean/I-clean-build.json').read_text())
with tempfile.TemporaryDirectory(prefix='b3-i2-review-') as tmp:
 d=pathlib.Path(tmp);manifest=(C/'bootstrap/c1.build').read_text();paths=[l.split()[1]for l in manifest.splitlines()if l.startswith(('source ','assembly '))]
 for p in paths:
  f=d/p;f.parent.mkdir(parents=True,exist_ok=True);f.write_bytes((C/p).read_bytes())
 (d/'build').mkdir()
 for i in [1,2,3]:
  f=d/f'bootstrap/c{i}.build';f.write_bytes((C/f'bootstrap/c{i}.build').read_bytes())
 stats=[];traces=[]
 for i in [1,2,3]:
  args=[str(C/'target/debug/core-s'),'project','bootstrap/c1.build']if i==1 else[q,'-s','1048576','-strace',f'build/c{i-1}.elf','build',f'bootstrap/c{i}.build']
  p=subprocess.run(args,cwd=d,env={'PATH':''},capture_output=True,timeout=90);assert p.returncode==0,p.stderr.decode()[-3000:]
  assert sha(d/f'build/c{i}.elf')==author['hashes'][f'c{i}'];assert sha(C/f'build/c{i}.elf')==author['hashes'][f'c{i}']
  if i>1:
   trace=p.stderr.decode();opened=re.findall(r'openat\([^,]+,"([^"]+)"',trace);assert set(opened)<=set(paths+[f'bootstrap/c{i}.build',f'build/c{i}.elf']);assert 'execve('not in trace
   traces.append({'generation':i,'opened':opened,'stderr':trace})
 assert(d/'build/c2.elf').read_bytes()==(d/'build/c3.elf').read_bytes()
 result['rebuilt_hashes']={f'c{i}':sha(d/f'build/c{i}.elf')for i in [1,2,3]};result['traces']=traces
 cases=[('short','fn run()->u32{return 37;}','run',True),('root','fn run()->u32{return 37;}','root::run',True),('module','module app;fn run()->u32{return 37;}','app::run',True),('module_absolute','module app;fn run()->u32{return 37;}','root::app::run',True),('double_prefix','fn run()->u32{return 37;}','root::root::run',False),('empty_after_prefix','fn run()->u32{return 37;}','root::',False),('missing','fn run()->u32{return 37;}','root::missing',False),('unsafe','unsafe fn run()->u32{return 37;}','root::run',False),('arguments','fn run(x:u32)->u32{return x;}','root::run',False),('wrong_result','fn run()->usize{return 37;}','root::run',False)]
 for name,source,entry,ok in cases:
  case=d/name;case.mkdir();(case/'in.vt').write_text(source)
  for gen in [0,1,2,3]:
   (case/'p.build').write_text(f'format 1\nprofile linux-user\nentry {entry}\nsource in.vt\noutput c{gen}.elf\n')
   args=[str(C/'target/debug/core-s'),'project','p.build']if gen==0 else[q,'-s','1048576',str(d/f'build/c{gen}.elf'),'build','p.build']
   p=subprocess.run(args,cwd=case,env={'PATH':''},capture_output=True,timeout=10);assert(p.returncode==0)==ok,(name,gen,p.returncode,p.stderr)
   row={'case':name,'gen':gen,'exit':p.returncode,'stderr':p.stderr.decode()}
   if ok:
    status=subprocess.run([q,str(case/f'c{gen}.elf')],timeout=10).returncode;assert status==37;row['program_exit']=status;(case/f'c{gen}.elf').unlink()
   else:assert not(case/f'c{gen}.elf').exists()
   if gen>0:
    args[-2]='check';p=subprocess.run(args,cwd=case,env={'PATH':''},capture_output=True,timeout=10);assert(p.returncode==0)==ok;assert not(case/f'c{gen}.elf').exists();row['check_exit']=p.returncode
   result['checks'].append(row)
Path=pathlib.Path
Path('/tmp/b3-i2-review.json').write_text(json.dumps(result,indent=2)+'\n');print('Independent source-only C1/C2/C3 rebuild + 40 build/30 check entry cases passed')
